function heapPush(arr, val, cmp){
  cmp = cmp || function(a,b){ return a<b; };
  var h = arr.slice();
  h.push(val);
  var i = h.length-1;
  while(i>0){
    var p=(i-1)>>1;
    if(cmp(h[i], h[p])){ var t=h[i]; h[i]=h[p]; h[p]=t; i=p; } else break;
  }
  return h;
}
function heapPop(arr, cmp){
  cmp = cmp || function(a,b){ return a<b; };
  if(arr.length===0) return {value:undefined, heap:[]};
  var h=arr.slice();
  var top=h[0];
  var last=h.pop();
  if(h.length>0){
    h[0]=last; var n=h.length, i=0;
    while(true){
      var l=2*i+1, r=2*i+2, m=i;
      if(l<n && cmp(h[l],h[m])) m=l;
      if(r<n && cmp(h[r],h[m])) m=r;
      if(m===i) break;
      var t=h[i]; h[i]=h[m]; h[m]=t; i=m;
    }
  }
  return {value:top, heap:h};
}
function heapify(arr, cmp){ cmp=cmp||function(a,b){return a<b;}; var h=[]; for(var i=0;i<arr.length;i++) h=heapPush(h,arr[i],cmp); return h; }
function heapSort(arr, cmp){
  cmp=cmp||function(a,b){return a<b;};
  var h=heapify(arr, cmp), out=[];
  while(h.length){ var r=heapPop(h, cmp); out.push(r.value); h=r.heap; }
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { heapPush:heapPush, heapPop:heapPop, heapify:heapify, heapSort:heapSort };
}
if (typeof window !== 'undefined') {
  window.HeapForgePure = { heapPush:heapPush, heapPop:heapPop, heapify:heapify, heapSort:heapSort };
